        createTask.run(id, title);
      }
      response.writeHead(303, { Location: projectLocation(id, filter, selectedPriority) });
      response.end();
    } else {
      sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><a href="/">Projects</a>'));
